import React, { useState, useEffect } from 'react';
import { api } from '../services/api';

const PanelProfesor = () => {
  const [bloqueos, setBloqueos] = useState([]);
  const [laboratorios, setLaboratorios] = useState([]);
  const [equipos, setEquipos] = useState([]);
  const [reservas, setReservas] = useState([]);
  const [formVisible, setFormVisible] = useState(false);
  const [verReservas, setVerReservas] = useState(false);
  const [labSeleccionado, setLabSeleccionado] = useState('');
  const [formData, setFormData] = useState({
    laboratorioId: '',
    equipoCodigo: '',
    inicio: '',
    fin: '',
    motivo: ''
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  useEffect(() => {
    if (formData.laboratorioId) {
      cargarEquipos(formData.laboratorioId);
    }
  }, [formData.laboratorioId]);

  useEffect(() => {
    if (labSeleccionado) {
      cargarReservas(labSeleccionado);
    }
  }, [labSeleccionado]);

  const cargarDatos = async () => {
    try {
      const [labsRes, bloqRes] = await Promise.all([
        api.get('/disponibilidad/laboratorios'),
        api.get('/bloqueos/mis-bloqueos')
      ]);

      setLaboratorios(labsRes.data);
      if (bloqRes.data.success) {
        setBloqueos(bloqRes.data.data);
      }
    } catch (error) {
      console.error('Error al cargar datos:', error);
    }
  };

  const cargarEquipos = async (laboratorioId) => {
    try {
      const response = await api.get(`/disponibilidad/equipos/${laboratorioId}`);
      if (response.data.success) {
        setEquipos(response.data.data || []);
      } else {
        setEquipos([]);
      }
    } catch (error) {
      console.error('Error al cargar equipos:', error);
      setEquipos([]);
    }
  };

  const cargarReservas = async (laboratorioId) => {
    try {
      const response = await api.get(`/reservas/laboratorio/${laboratorioId}`);
      if (response.data.success) {
        setReservas(response.data.data);
      }
    } catch (error) {
      console.error('Error al cargar reservas:', error);
      setReservas([]);
    }
  };

  const crearBloqueo = async (e) => {
    e.preventDefault();

    try {
      const response = await api.post('/bloqueos', formData);
      if (response.data.success) {
        alert('✅ Bloqueo creado exitosamente');
        setFormVisible(false);
        setFormData({
          laboratorioId: '',
          equipoCodigo: '',
          inicio: '',
          fin: '',
          motivo: ''
        });
        setEquipos([]);
        cargarDatos();
      }
    } catch (error) {
      alert(error.response?.data?.message || 'Error al crear bloqueo');
    }
  };

  const desbloquear = async (id) => {
    if (!window.confirm('¿Desbloquear?')) return;

    try {
      const response = await api.put(`/bloqueos/${id}/desbloquear`);
      if (response.data.success) {
        alert('✅ Desbloqueado exitosamente');
        cargarDatos();
      }
    } catch (error) {
      alert('Error al desbloquear');
    }
  };

  return (
    <div className="animate-fadeIn">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h2 className="text-4xl font-extrabold bg-gradient-to-r from-orange-600 to-red-600 bg-clip-text text-transparent mb-2">
            Panel de Profesor
          </h2>
          <p className="text-gray-600 text-lg">Gestiona bloqueos y supervisa reservas</p>
        </div>
        <div className="flex gap-4">
          <button
            onClick={() => {
              setVerReservas(!verReservas);
              setFormVisible(false);
            }}
            className={`px-6 py-3 rounded-xl font-bold transition-all duration-300 transform hover:scale-105 ${
              verReservas 
                ? 'bg-gradient-to-r from-red-500 to-pink-600 text-white shadow-lg' 
                : 'bg-gradient-to-r from-green-500 to-emerald-600 text-white shadow-lg'
            }`}
          >
            <span className="flex items-center space-x-2">
              <span className="text-xl">{verReservas ? '❌' : '📋'}</span>
              <span>{verReservas ? 'Cerrar' : 'Ver Reservas'}</span>
            </span>
          </button>
          <button
            onClick={() => {
              setFormVisible(!formVisible);
              setVerReservas(false);
            }}
            className={`px-6 py-3 rounded-xl font-bold transition-all duration-300 transform hover:scale-105 ${
              formVisible 
                ? 'bg-gradient-to-r from-red-500 to-pink-600 text-white shadow-lg' 
                : 'btn-warning shadow-lg'
            }`}
          >
            <span className="flex items-center space-x-2">
              <span className="text-xl">{formVisible ? '❌' : '🔒'}</span>
              <span>{formVisible ? 'Cancelar' : 'Nuevo Bloqueo'}</span>
            </span>
          </button>
        </div>
      </div>

      {formVisible && (
        <div className="card-gradient p-8 mb-8 shadow-xl animate-fadeIn">
          <div className="flex items-center space-x-3 mb-6">
            <span className="text-4xl">🔒</span>
            <h3 className="text-2xl font-extrabold text-gray-900">
              Crear Bloqueo de Equipo
            </h3>
          </div>

          <form onSubmit={crearBloqueo} className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-xl mr-2">🏢</span>
                Laboratorio *
              </label>
              <select
                value={formData.laboratorioId}
                onChange={(e) => setFormData({...formData, laboratorioId: e.target.value, equipoCodigo: ''})}
                className="input-field"
                required
              >
                <option value="">Seleccionar laboratorio</option>
                {laboratorios.map(lab => (
                  <option key={lab.id} value={lab.id}>{lab.nombre}</option>
                ))}
              </select>
            </div>

            {formData.laboratorioId && (
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                  <span className="text-xl mr-2">🖥️</span>
                  Equipo (opcional - dejar vacío para bloquear todo el laboratorio)
                </label>
                <select
                  value={formData.equipoCodigo}
                  onChange={(e) => setFormData({...formData, equipoCodigo: e.target.value})}
                  className="input-field"
                >
                  <option value="">🔒 Bloquear TODO el laboratorio</option>
                  {equipos.length > 0 ? (
                    equipos.map(equipo => (
                      <option key={equipo.id} value={equipo.codigo}>
                        {equipo.codigo} ({equipo.tipo})
                      </option>
                    ))
                  ) : (
                    <option disabled>Cargando equipos...</option>
                  )}
                </select>
                {equipos.length === 0 && formData.laboratorioId && (
                  <p className="text-sm text-amber-700 mt-2 font-semibold flex items-center">
                    <span className="mr-2">⚠️</span>
                    No se encontraron equipos en este laboratorio
                  </p>
                )}
              </div>
            )}

            <div className="grid grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                  <span className="text-xl mr-2">📅</span>
                  Fecha y Hora de Inicio *
                </label>
                <input
                  type="datetime-local"
                  value={formData.inicio}
                  onChange={(e) => setFormData({...formData, inicio: e.target.value})}
                  className="input-field"
                  min={new Date().toISOString().slice(0, 16)}
                  required
                />
                <p className="text-xs text-gray-500 mt-2 font-medium">
                  Ejemplo: 24/11/2025 3:00 PM
                </p>
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                  <span className="text-xl mr-2">🏁</span>
                  Fecha y Hora de Fin *
                </label>
                <input
                  type="datetime-local"
                  value={formData.fin}
                  onChange={(e) => setFormData({...formData, fin: e.target.value})}
                  className="input-field"
                  min={formData.inicio || new Date().toISOString().slice(0, 16)}
                  required
                />
                <p className="text-xs text-gray-500 mt-2 font-medium">
                  Ejemplo: 24/11/2025 7:00 PM
                </p>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-xl mr-2">📝</span>
                Motivo *
              </label>
              <textarea
                value={formData.motivo}
                onChange={(e) => setFormData({...formData, motivo: e.target.value})}
                className="input-field"
                rows="4"
                placeholder="Ej: Mantenimiento preventivo, Actualización de software, etc."
                required
              />
            </div>

            <button type="submit" className="btn-warning w-full py-4 text-lg">
              <span className="flex items-center justify-center">
                <span className="text-2xl mr-2">🔒</span>
                Crear Bloqueo
              </span>
            </button>
          </form>
        </div>
      )}

      {verReservas && (
        <div className="card-gradient p-8 mb-8 shadow-xl animate-fadeIn">
          <div className="flex items-center space-x-3 mb-6">
            <span className="text-4xl">📋</span>
            <h3 className="text-2xl font-extrabold text-gray-900">
              Ver Reservas por Laboratorio
            </h3>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
              <span className="text-xl mr-2">🏢</span>
              Seleccionar Laboratorio
            </label>
            <select
              value={labSeleccionado}
              onChange={(e) => setLabSeleccionado(e.target.value)}
              className="input-field"
            >
              <option value="">Seleccionar laboratorio</option>
              {laboratorios.map(lab => (
                <option key={lab.id} value={lab.id}>{lab.nombre}</option>
              ))}
            </select>
          </div>

          {labSeleccionado && (
            <div className="space-y-4">
              <div className="flex items-center space-x-3 mb-4">
                <span className="text-2xl">✅</span>
                <h4 className="font-bold text-xl text-gray-800">
                  Reservas Activas ({reservas.length})
                </h4>
              </div>
              {reservas.length > 0 ? (
                reservas.map(reserva => (
                  <div key={reserva.id} className="bg-white border-2 border-purple-200 rounded-xl p-6 hover:shadow-lg transition-shadow duration-300">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-3 mb-3">
                          <span className="text-2xl font-extrabold text-gray-900">
                            {reserva.equipoCodigo}
                          </span>
                          <span className={`badge ${
                            reserva.estado === 'PROGRAMADA' ? 'badge-info' :
                            reserva.estado === 'EN_CURSO' ? 'badge-success' :
                            'badge-gray'
                          }`}>
                            {reserva.estado.replace('_', ' ')}
                          </span>
                        </div>
                        <div className="text-base text-gray-700 space-y-2 font-medium">
                          <p className="flex items-center space-x-2">
                            <span className="text-xl">👤</span>
                            <span>Estudiante: {reserva.estudianteNombre}</span>
                          </p>
                          <p className="flex items-center space-x-2">
                            <span className="text-xl">📅</span>
                            <span>
                              {new Date(reserva.franja.inicio).toLocaleString('es-CO', {
                                year: 'numeric',
                                month: '2-digit',
                                day: '2-digit',
                                hour: '2-digit',
                                minute: '2-digit'
                              })} - {new Date(reserva.franja.fin).toLocaleTimeString('es-CO', {
                                hour: '2-digit',
                                minute: '2-digit'
                              })}
                            </span>
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-12">
                  <div className="text-6xl mb-4 animate-pulse-soft">📭</div>
                  <p className="text-gray-600 text-lg font-medium">
                    No hay reservas activas en este laboratorio
                  </p>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      <div>
        <div className="flex items-center space-x-3 mb-6">
          <span className="text-4xl">🔐</span>
          <h3 className="text-2xl font-extrabold text-gray-900">
            Mis Bloqueos
          </h3>
        </div>

        {bloqueos.length > 0 ? (
          <div className="space-y-5">
            {bloqueos.map(bloqueo => (
              <div key={bloqueo.id} className="card-gradient p-8 hover:scale-[1.02] transition-transform duration-300">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-4 mb-4">
                      <h4 className="text-2xl font-extrabold text-gray-900">
                        {bloqueo.motivo}
                      </h4>
                      <span className={`badge ${bloqueo.activo ? 'badge-danger' : 'badge-gray'}`}>
                        {bloqueo.activo ? '🔒 Activo' : '🔓 Inactivo'}
                      </span>
                    </div>

                    <div className="text-base text-gray-700 space-y-2 font-medium">
                      <p className="flex items-center space-x-2">
                        <span className="text-xl">📅</span>
                        <span>
                          {new Date(bloqueo.franja.inicio).toLocaleString('es-CO', {
                            weekday: 'long',
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </span>
                      </p>
                      <p className="flex items-center space-x-2">
                        <span className="text-xl">🏁</span>
                        <span>
                          {new Date(bloqueo.franja.fin).toLocaleString('es-CO', {
                            weekday: 'long',
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </span>
                      </p>
                    </div>
                  </div>

                  {bloqueo.activo && (
                    <button
                      onClick={() => desbloquear(bloqueo.id)}
                      className="btn-success text-base px-6 py-3"
                    >
                      <span className="flex items-center space-x-2">
                        <span className="text-xl">🔓</span>
                        <span>Desbloquear</span>
                      </span>
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="text-8xl mb-6 animate-pulse-soft">🔐</div>
            <p className="text-xl text-gray-600 font-medium">No hay bloqueos registrados</p>
            <p className="text-sm text-gray-500 mt-2">Crea un nuevo bloqueo usando el botón superior</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PanelProfesor;
